                    <span className="text-[10px] font-black uppercase tracking-widest">Exit Sim</span>
                  </button>
                ) : (
                  <>
                    <button onClick={() => setIsSimulating(!isSimulating)} className="flex items-center space-x-2 px-4 py-2 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all bg-transparent border-white/10 text-zinc-400 hover:text-white hover:border-white/20">
                      <MonitorPlay size={14} />
                      <span className="hidden sm:inline">Simulate</span>
                    </button>
                    <button onClick={() => setShowChart(!showChart)} className={`p-2 rounded-xl border transition-all ${showChart ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-transparent border-white/10 text-zinc-500 hover:text-white'}`}>
                      <LineChart size={16} />
                    </button>
                  </>
                )}
              </div>

              <div className="mt-auto">
                <p className={`text-[10px] font-black uppercase tracking-[0.4em] mb-2 ${isSimulating ? 'text-amber-400' : 'text-zinc-500'}`}>
                  {isSimulating ? `SCENARIO: ${currentScenario.name.toUpperCase()}` : 'Portfolio Net Worth'}
                </p>

                <div className="flex flex-col md:flex-row md:items-center md:space-x-8">
                  <h2 className={`text-5xl md:text-7xl lg:text-8xl font-bold tracking-tighter leading-none ${isSimulating ? 'bg-gradient-to-r from-violet-400 to-fuchsia-400 bg-clip-text text-transparent' : 'text-white'}`}>
                    ${simulatedValue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </h2>
                  {isSimulating && (
                    <div className={`mt-4 md:mt-0 flex items-center space-x-2 px-4 py-2 rounded-xl border text-[11px] font-black uppercase tracking-widest animate-in slide-in-from-left-4 ${simulatedDelta >= 0 ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'}`}>
                      {simulatedDelta >= 0 ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
                      <span>{simulatedDelta >= 0 ? '+' : ''}${Math.abs(simulatedDelta).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} Potential</span>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {showChart && !isSimulating && (
              <div className="flex-1 border-t border-white/5 flex flex-col bg-black/20 animate-in fade-in duration-700">
                <div className="px-12 py-6 flex items-center space-x-6">
                  {['1H', '1D', '1W', '1M', '1Y', 'ALL'].map((tf) => (
                    <button key={tf} onClick={() => setActiveTimeframe(tf)} className={`text-[9px] font-black uppercase tracking-widest pb-1 transition-all ${activeTimeframe === tf ? 'text-emerald-500 border-b-2 border-emerald-500' : 'text-zinc-500 hover:text-zinc-300 border-b-2 border-transparent'}`}>{tf}</button>
                  ))}
                </div>
                <div className="flex-1 px-8 pb-4 relative">
                  <ResponsiveContainer width="100%" height={240}>
                    <AreaChart data={STACKED_CHART_DATA} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                      <defs>
                        <linearGradient id="pepeColor" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#10b981" stopOpacity={0.5}/><stop offset="95%" stopColor="#10b981" stopOpacity={0.2}/></linearGradient>
                      </defs>
                      <CartesianGrid vertical={false} stroke="#ffffff05" />
                      <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{ fill: '#52525b', fontSize: 10, fontWeight: 700 }} dy={10} />
                      <Tooltip contentStyle={{ backgroundColor: '#18181b', border: '1px solid #27272a', borderRadius: '12px' }} />
                      <Area stackId="1" type="monotone" dataKey="total" stroke="#10b981" strokeWidth={2} fill="url(#pepeColor)" />
                      <ReferenceLine x="Nov 12" stroke="#ffffff11" strokeDasharray="5 5" />
                    </AreaChart>
                  </ResponsiveContainer>
                </div>
              </div>
            )}
          </div>
        </div>

        <AssetsTable onTradeClick={onTradeClick} />
      </div>

      {/* COLUMN 2: INTELLIGENCE PANEL (30%) */}
      <div className="w-full lg:w-[350px] xl:w-[420px] bg-[#080808] border-l border-white/10 flex flex-col overflow-y-auto scrollbar-hide h-full">

        <div className="p-6 border-b border-white/5 bg-[#0a0a0a]/50 flex items-center justify-between">
          <div className="flex flex-col">
            <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-zinc-400">Neural Intelligence</h2>
            <p className="text-[8px] font-bold text-zinc-600 uppercase tracking-widest mt-1">CPU Alpha-V4 • Active</p>
          </div>
          <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
        </div>

        <div className="p-6 space-y-8">

          {/* HIGH CONTRAST STRATEGY NODE */}
          <section className="space-y-4">
            {!showStrategy ? (
              /* STATE 1: COLLAPSED (THE HOOK) */
              <div className="bg-zinc-900 border-2 border-zinc-800 rounded-3xl p-6 shadow-2xl relative group overflow-hidden transition-all hover:border-emerald-500/30">
                <div className="flex flex-col space-y-6">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em]">Recommended Action</span>
                    <Sparkles size={16} className="text-emerald-400 animate-pulse" />
                  </div>

                  <div>
                    <h3 className="text-4xl font-bold text-emerald-400 tracking-tighter">+$1,240.50</h3>
                    <p className="text-sm font-bold text-white mt-1 flex items-center gap-2">
                       Risk Reduction: <span className="text-rose-400">High</span> <ArrowRight size={14} /> <span className="text-emerald-400">Low</span>
                    </p>
                  </div>

                  <button 
                    onClick={handleGenerateStrategy}
                    disabled={isGenerating}
                    className="w-full py-4 bg-white text-black rounded-2xl font-black text-[12px] uppercase tracking-[0.2em] shadow-xl transition-all hover:bg-emerald-400 active:scale-95 flex items-center justify-center space-x-2"
                  >
                    {isGenerating ? (
                      <>
                        <Loader2 size={16} className="animate-spin" />
                        <span>Analyzing...</span>
                      </>
                    ) : (
                      <>
                        <span>Review Plan</span>
                        <ChevronRight size={16} />
                      </>
                    )}
                  </button>
                </div>
              </div>
            ) : (
              /* STATE 2: EXPANDED (THE PLAN) */
              <div className="bg-zinc-900 border-2 border-zinc-700 rounded-3xl overflow-hidden animate-in zoom-in-95 duration-300 shadow-2xl flex flex-col">
                {/* Header */}
                <div className="p-6 border-b border-zinc-800 flex items-center justify-between bg-zinc-900/50">
                   <h3 className="text-lg font-bold text-white tracking-tight">Optimization Plan</h3>
                   <button onClick={() => setShowStrategy(false)} className="text-zinc-400 hover:text-white transition-colors bg-zinc-800 p-2 rounded-xl">
                     <X size={18}/>
                   </button>
                </div>

                <div className="p-6 space-y-8">
                  {/* Before/After Visualization */}
                  <div className="bg-black/40 border border-zinc-800 rounded-2xl p-4 flex items-center justify-between">
                     <div className="flex flex-col items-center">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Current</span>
                        <div className="flex items-center gap-2 text-rose-500">
                           <ShieldAlert size={18} />
                           <span className="font-mono font-bold text-lg">HIGH</span>
                        </div>
                     </div>
                     <ArrowRightCircle size={24} className="text-zinc-700" />
                     <div className="flex flex-col items-center">
                        <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Target</span>
                        <div className="flex items-center gap-2 text-emerald-500">
                           <Shield size={18} />
                           <span className="font-mono font-bold text-lg">SAFE</span>
                        </div>
                     </div>
                  </div>

                  {/* Actions List */}
                  <div className="space-y-4">
                    <div className="p-4 bg-zinc-950 border border-zinc-700 rounded-2xl flex justify-between items-center group">
                       <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-rose-500/10 rounded-xl flex items-center justify-center border border-rose-500/20">
                             <ArrowDownCircle className="text-rose-500" size={20} />
                          </div>
                          <div>
                             <p className="text-sm font-bold text-white">Sell PEPE</p>
                             <p className="text-[10px] font-black text-zinc-500 uppercase">Excess Volatility</p>
                          </div>
                       </div>
                       <span className="text-lg font-mono font-bold text-rose-500">-$1,080</span>
                    </div>

                    <div className="p-4 bg-zinc-950 border border-zinc-700 rounded-2xl flex justify-between items-center">
                       <div className="flex items-center gap-4">
                          <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center border border-emerald-500/20">
                             <ArrowUpCircle className="text-emerald-500" size={20} />
                          </div>
                          <div>
                             <p className="text-sm font-bold text-white">Lend USDC</p>
                             <p className="text-[10px] font-black text-zinc-500 uppercase">Yield Accrual</p>
                          </div>
                       </div>
                       <span className="text-lg font-mono font-bold text-emerald-500">+$1,075</span>
                    </div>
                  </div>

                  {/* Execution Footer */}
                  <div className="space-y-4">
                    <button 
                      onClick={handleExecute}
                      disabled={isExecuted}
                      className="w-full py-5 bg-emerald-500 hover:bg-emerald-400 text-black rounded-2xl font-black text-[13px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98]"
                    >
                      {isExecuted ? (
                        <div className="flex items-center justify-center space-x-2">
                          <Loader2 size={18} className="animate-spin" />
                          <span>Executing...</span>
                        </div>
                      ) : "Execute Bundle"}
                    </button>
                    <div className="flex justify-center items-center space-x-2 text-[11px] font-bold text-zinc-400 uppercase tracking-widest">
                       <span>Network Fee:</span>
                       <span className="text-zinc-200 font-mono">~$4.50</span>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </section>

          {/* OTHER STATS SECTIONS */}
          <section className="bg-zinc-900 border border-zinc-800 rounded-[2rem] p-6 hover:bg-zinc-900/60 transition-all">
             <div className="flex items-center justify-between mb-4">
                <div className="flex items-center space-x-3">
                  <Radar size={18} className="text-blue-500" />
                  <h3 className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em]">Whale Tracker</h3>
                </div>
                <button onClick={() => setIsWhaleDrawerOpen(true)} className="text-[10px] font-black text-blue-500 uppercase hover:underline">View All</button>
             </div>
             <div className="flex items-baseline space-x-2">
               <span className="text-4xl font-mono font-black text-white tracking-tighter">88%</span>
               <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">Alignment</span>
             </div>
          </section>

          <section className="bg-zinc-900 border border-zinc-800 rounded-[2rem] p-6">
             <div className="flex items-center space-x-3 mb-4">
               <ShieldAlert className="text-amber-500" size={18} />
               <span className="text-[10px] font-black text-zinc-400 uppercase tracking-[0.2em]">Market Risk</span>
             </div>
             <div className="flex items-baseline space-x-3">
               <span className="text-4xl font-mono font-black text-amber-500 tracking-tighter">4.2</span>
               <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest">MODERATE</span>
             </div>
          </section>

          <CryptoAI />
          <div className="pb-8"></div>
        </div>
      </div>

      <WhaleDrawer isOpen={isWhaleDrawerOpen} onClose={() => setIsWhaleDrawerOpen(false)} />
    </div>
  );
};

export default Dashboard;
